<?php
require dirname(__DIR__).'/includes/functions.php';require dirname(__DIR__).'/includes/data.php';header('Content-Type: application/json; charset=utf-8');$q=trim($_GET['q']??'');if(mb_strlen($q)<2){echo json_encode(['groups'=>[]]);exit;}$needle=mb_strtolower($q);$groups=['Safari'=>[],'Kilimanjaro'=>[],'Destination'=>[],'Experience'=>[],'Article'=>[]];foreach(all_public_packages() as $p){$hay=mb_strtolower(($p['title']??'').' '.($p['summary']??'').' '.($p['category']??'').' '.($p['location']??''));if(!str_contains($hay,$needle))continue;$cat=$p['category']??'';$g=$cat==='Kilimanjaro'?'Kilimanjaro':($cat==='Day Trips'?'Experience':'Safari');$groups[$g][]=['title'=>$p['title'],'url'=>'/package/'.$p['slug'],'meta'=>($p['days']??'').' days · '.$cat];}foreach(destinations() as $d){if(str_contains(mb_strtolower($d['name'].' '.$d['text']),$needle))$groups['Destination'][]=['title'=>$d['name'],'url'=>'/destination/'.$d['slug'],'meta'=>'Destination'];}foreach(published_articles() as $a){if(str_contains(mb_strtolower($a['title'].' '.$a['excerpt']),$needle))$groups['Article'][]=['title'=>$a['title'],'url'=>'/article/'.$a['slug'],'meta'=>'Travel Guide'];}foreach($groups as $k=>$items)$groups[$k]=array_slice($items,0,5);echo json_encode(['groups'=>$groups],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
